  "Ensayo no encontrado.": "Essai introuvable.",
  "Referencias metodológicas": "Références méthodologiques",
  "Cada registro es una unidad de análisis. Si contiene varias imágenes, no se cuentan como juicios independientes. Los filtros actuales definen la muestra; el cálculo no se limita a la página visible. Los ensayos almacenan los identificadores y valores originales de cada registro.": "Chaque fiche est une unité d'analyse. Si elle contient plusieurs images, celles-ci ne sont pas comptées comme des jugements indépendants. Les filtres actuels définissent l'échantillon ; le calcul ne se limite pas à la page visible. Les essais stockent les identifiants et les valeurs d'origine de chaque fiche.",
  "Unanimidad exige que todos los modelos seleccionados coincidan exactamente. «Al menos uno» exige coincidencia de algún modelo con la referencia humana; «todos», de todos ellos. Ambos usan registros completos de modelos y referencia. La mayoría es estricta: más de la mitad de los modelos debe dar la misma categoría o el mismo conjunto; se excluyen los casos sin mayoría de su porcentaje y se informa su número.": "L'unanimité exige que tous les modèles sélectionnés coïncident exactement. « Au moins un » exige la coïncidence d'au moins un modèle avec la référence humaine ; « tous », celle de tous. Les deux utilisent des fiches complètes de modèles et de référence. La majorité est stricte : plus de la moitié des modèles doivent donner la même catégorie ou le même ensemble ; les cas sans majorité sont exclus de son pourcentage et leur nombre est indiqué.",
  "κ = (Po − Pe) / (1 − Pe). Po es el acuerdo observado y Pe procede de los marginales de cada evaluador. El kappa nominal no presupone orden. El ponderado usa distancias lineales o cuadráticas entre categorías de una escala ordinal declarada. No es adecuado imponer un orden a temas históricos.": "κ = (Po − Pe) / (1 − Pe). Po est l'accord observé et Pe provient des marginales de chaque évaluateur. Le kappa nominal ne présuppose aucun ordre. Le kappa pondéré utilise des distances linéaires ou quadratiques entre les catégories d'une échelle ordinale déclarée. Il n'est pas adapté d'imposer un ordre à des thèmes historiques.",
  "Fleiss usa un número fijo de evaluadores y casos completos del grupo. Alfa nominal usa coincidencias ponderadas por el número de juicios válidos de cada registro y excluye las unidades con menos de dos. Elegir casos completos para todos restringe también estos índices. No se asigna un valor ficticio cuando falta variación o muestra.": "Fleiss utilise un nombre fixe d'évaluateurs et les cas complets du groupe. L'alpha nominal utilise des coïncidences pondérées par le nombre de jugements valides de chaque fiche et exclut les unités comptant moins de deux jugements. Choisir les cas complets pour tous restreint aussi ces indices. Aucune valeur fictive n'est attribuée lorsque la variation ou l'échantillon fait défaut.",
  "El acuerdo exacto compara conjuntos sin atender al orden. Jaccard es la media de intersección / unión por registro; dos conjuntos vacíos válidos tienen Jaccard 1. El kappa binario por categoría compara presencia y ausencia en registros con ambos juicios válidos. No se informa un kappa nominal global ni Fleiss o alfa global para etiquetas mezcladas.": "L'accord exact compare des ensembles sans tenir compte de l'ordre. Jaccard est la moyenne de intersection / union par fiche ; deux ensembles vides valides ont un Jaccard de 1. Le kappa binaire par catégorie compare présence et absence dans les fiches ayant deux jugements valides. Aucun kappa nominal global, ni Fleiss ou alpha global, n'est fourni pour les étiquettes mélangées.",
  "En cada pareja, A es la referencia direccional; si interviene el investigador, A es su columna. Precisión = ambos / B; sensibilidad = ambos / A; F1 = 2 × ambos / (A + B). F1 micro agrega recuentos y F1 macro promedia las categorías observadas en esa pareja. Las categorías ausentes en ambos no se incorporan artificialmente. No se asume que la clasificación humana sea infalible.": "Pour chaque paire, A est la référence directionnelle ; si le chercheur intervient, A est sa colonne. Précision = les deux / B ; sensibilité = les deux / A ; F1 = 2 × les deux / (A + B). Le F1 micro agrège les effectifs et le F1 macro fait la moyenne des catégories observées dans cette paire. Les catégories absentes des deux ne sont pas intégrées artificiellement. On ne suppose pas que la classification humaine soit infaillible.",
  "Los vacíos y los valores inválidos se excluyen, no se consideran acuerdos. Puedes declarar [] como conjunto vacío válido en selección múltiple; una celda nula sigue siendo un dato ausente. Se normaliza Unicode NFKC y se recortan espacios; opcionalmente se ignoran mayúsculas. Las tildes se conservan. Las opciones de distintas columnas se comparan por etiqueta, no por identificador. Las equivalencias son explícitas y se aplican una sola vez.": "Les vides et les valeurs invalides sont exclus, ils ne sont pas considérés comme des accords. Vous pouvez déclarer [] comme ensemble vide valide en sélection multiple ; une cellule nulle reste une donnée absente. L'Unicode est normalisé en NFKC et les espaces sont rognées ; les majuscules peuvent être ignorées en option. Les accents sont conservés. Les options de colonnes différentes sont comparées par étiquette, et non par identifiant. Les équivalences sont explicites et ne s'appliquent qu'une seule fois.",
  "El intervalo del acuerdo exacto es Wilson al 95% y presupone registros independientes. No es un intervalo de kappa ni una prueba de superioridad entre modelos. Imágenes del mismo libro, fotógrafo o serie pueden estar relacionadas; diseña el muestreo con esa dependencia en mente. Examina cobertura, prevalencia, confusiones y sesgos junto a los índices; un acuerdo alto no demuestra exactitud histórica.": "L'intervalle de l'accord exact est celui de Wilson à 95 % et suppose des fiches indépendantes. Ce n'est pas un intervalle de kappa ni un test de supériorité entre modèles. Les images d'un même livre, photographe ou série peuvent être liées ; concevez l'échantillonnage en tenant compte de cette dépendance. Examinez la couverture, la prévalence, les confusions et les biais en plus des indices ; un accord élevé ne démontre pas l'exactitude historique.",
  "Guardar conserva una instantánea local con configuración, opciones y valores originales, normalizados y procedencia disponible. Exporta JSON para reproducir todos los resultados; CSV ofrece tablas en formato largo con secciones de métricas, categorías, confusiones y registros. Las imágenes permanecen en la colección. Las nuevas ejecuciones no sobrescriben los ensayos anteriores.": "Enregistrer conserve un instantané local avec la configuration, les options et les valeurs d'origine, normalisées, ainsi que la provenance disponible. Exportez en JSON pour reproduire tous les résultats ; le CSV propose des tableaux au format long avec des sections de métriques, de catégories, de confusions et de fiches. Les images restent dans la collection. Les nouvelles exécutions n'écrasent pas les essais précédents.",
  "IC 95%": "IC à 95 %",
  "Estos campos documentan el ensayo. Genera las clasificaciones desde Analizar y los ajustes de modelos; usa una columna independiente para cada ejecución.": "Ces champs documentent l'essai. Générez les classifications depuis Analyser et les réglages des modèles ; utilisez une colonne indépendante pour chaque exécution.",
  "Los ensayos difieren en registros, referencia humana, categorías o reglas de cálculo. Los porcentajes no permiten una comparación directa de rendimiento.": "Les essais diffèrent par les fiches, la référence humaine, les catégories ou les règles de calcul. Les pourcentages ne permettent pas une comparaison directe des performances.",
  "Concordancia": "Concordance",
