  "Solo registros con imágenes": "Uniquement les fiches avec images",
  "Las tildes se conservan. Los vacíos no se convierten en coincidencias. Usa columnas categóricas, no descripciones completas.": "Les accents sont conservés. Les vides ne deviennent pas des coïncidences. Utilisez des colonnes catégorielles, et non des descriptions complètes.",
