  "Se guarda también la procedencia disponible de las propuestas de IA. La identificación manual del ensayo no sustituye el historial de cada celda.": "La provenance disponible des propositions d'IA est également enregistrée. L'identification manuelle de l'essai ne remplace pas l'historique de chaque cellule.",
  "Equivalencias entre categorías": "Équivalences entre catégories",
  "Cada equivalencia transforma una etiqueta de una columna en una categoría común. Se aplica una sola vez y no modifica los datos originales.": "Chaque équivalence transforme une étiquette d'une colonne en catégorie commune. Elle s'applique une seule fois et ne modifie pas les données d'origine.",
