  "Escala ordinal y kappa ponderado (opcional)": "Échelle ordinale et kappa pondéré (facultatif)",
  "Las categorías temáticas son nominales. Activa pesos solo si tus categorías tienen un orden justificable, como grados de intensidad.": "Les catégories thématiques sont nominales. N'activez les poids que si vos catégories ont un ordre justifiable, comme des degrés d'intensité.",
