  "Editar configuración": "Modifier la configuration",
  "La configuración o los filtros actuales difieren de esta instantánea. Guardar y exportar conservan el resultado mostrado; recalcular crea uno nuevo.": "La configuration ou les filtres actuels diffèrent de cet instantané. Enregistrer et exporter conservent le résultat affiché ; recalculer en crée un nouveau.",
  "Los resultados son una instantánea; las ediciones posteriores y las nuevas tareas de IA no la alteran.": "Les résultats sont un instantané ; les modifications ultérieures et les nouvelles tâches d'IA ne l'altèrent pas.",
  "No hay registros en este conjunto. Revisa los filtros y la opción de imágenes.": "Aucune fiche dans cet ensemble. Vérifiez les filtres et l'option des images.",
  "Unanimidad entre modelos": "Unanimité entre modèles",
  "Solo registros con todos los modelos válidos.": "Uniquement les fiches avec tous les modèles valides.",
  "Al menos un modelo coincide con el investigador": "Au moins un modèle coïncide avec le chercheur",
