  "Los porcentajes «al menos uno» y «todos» usan los casos completos de todos los modelos y la referencia humana.": "Les pourcentages « au moins un » et « tous » utilisent les cas complets de tous les modèles et de la référence humaine.",
  "registros con unanimidad de modelos diferente de la referencia.": "fiches avec unanimité des modèles différente de la référence.",
