  "Cobertura": "Couverture",
  "Inválidos: opciones borradas, texto demasiado largo o varias categorías en modo de categoría única. Revisa esos registros antes de interpretar el resultado.": "Invalides : options supprimées, texte trop long ou plusieurs catégories en mode catégorie unique. Vérifiez ces fiches avant d'interpréter le résultat.",
  "Acuerdo del conjunto de evaluadores": "Accord de l'ensemble d'évaluateurs",
  "Grupo": "Groupe",
  "Casos completos": "Cas complets",
  "Casos / juicios para α": "Cas / jugements pour α",
  "Solo modelos": "Modèles uniquement",
  "Modelos e investigador": "Modèles et chercheur",
  "Fleiss usa casos completos del grupo. Alfa nominal aprovecha registros con al menos dos juicios válidos, salvo que hayas elegido casos completos para todos.": "Fleiss utilise les cas complets du groupe. L'alpha nominal exploite les fiches comportant au moins deux jugements valides, sauf si vous avez choisi les cas complets pour tous.",
  "Comparación por parejas": "Comparaison par paires",
  "Selecciona una pareja para explorar categorías y confusiones. Cada n cuenta registros, no etiquetas.": "Sélectionnez une paire pour explorer les catégories et les confusions. Chaque n compte des fiches, pas des étiquettes.",
  "Pareja": "Paire",
  "Acuerdo exacto": "Accord exact",
  "κ ponderado": "κ pondéré",
  "excluidos": "exclues",
  "A es la referencia para las métricas direccionales. Con el investigador, A siempre es su columna. Coincidir con una referencia no demuestra por sí solo la verdad histórica.": "A est la référence pour les métriques directionnelles. Avec le chercheur, A est toujours sa colonne. Concorder avec une référence ne prouve pas à lui seul la vérité historique.",
  "Buscar categoría en resultados": "Rechercher une catégorie dans les résultats",
  "Categorías y sesgos de asignación": "Catégories et biais d'attribution",
  "La diferencia B − A muestra sobreasignación o infraasignación frente a la referencia en esta pareja.": "La différence B − A indique une sur-attribution ou une sous-attribution par rapport à la référence dans cette paire.",
  "Categoría": "Catégorie",
  "Ambos": "Les deux",
  "Precisión": "Précision",
  "Sensibilidad": "Sensibilité",
  "binario": "binaire",
  "Matriz de confusión (formato de pares)": "Matrice de confusion (format de paires)",
  "Cruces de conjuntos de etiquetas": "Croisements d'ensembles d'étiquettes",
  "Se muestran los cruces observados, incluidos los acuerdos. A = filas de referencia; B = asignaciones comparadas. Los cruces no mostrados tienen frecuencia cero.": "Les croisements observés sont affichés, accords compris. A = lignes de référence ; B = attributions comparées. Les croisements non affichés ont une fréquence nulle.",
