  "Incluye valores originales, etiquetas normalizadas, opciones, filtros, instrucciones, procedencia disponible y resultados. No incluye los archivos de imagen.": "Inclut les valeurs d'origine, les étiquettes normalisées, les options, les filtres, les instructions, la provenance disponible et les résultats. N'inclut pas les fichiers image.",
