  "La procedencia registra propuestas históricas. Puede contener varios modelos o instrucciones por columna; revisa su homogeneidad antes de comparar ensayos.": "La provenance enregistre des propositions historiques. Une colonne peut contenir plusieurs modèles ou instructions ; vérifiez son homogénéité avant de comparer des essais.",
  "Ensayos guardados en esta base de datos": "Essais enregistrés dans cette base de données",
  "Cada ensayo conserva sus datos y condiciones. Puedes abrirlo, reutilizar su configuración y calcular otro con los filtros actuales. Las copias de seguridad incluyen los ensayos.": "Chaque essai conserve ses données et ses conditions. Vous pouvez l'ouvrir, réutiliser sa configuration et en calculer un autre avec les filtres actuels. Les sauvegardes incluent les essais.",
