  "Limpiar comparación": "Effacer la comparaison",
  "Los ensayos no comparten exactamente los registros, la referencia humana o el tipo de clasificación. Los porcentajes no permiten una comparación directa de rendimiento.": "Les essais ne partagent pas exactement les mêmes fiches, la même référence humaine ou le même type de classification. Les pourcentages ne permettent pas une comparaison directe des performances.",
  "Compara también denominadores, cobertura, taxonomías e instrucciones. Cambiar el número de modelos cambia la interpretación de unanimidad y «al menos uno».": "Comparez aussi les dénominateurs, la couverture, les taxonomies et les instructions. Changer le nombre de modèles modifie l'interprétation de l'unanimité et de « au moins un ».",
