  "Importar «-», «s.d.», «n/a» y similares como celdas vacías": "Importer « - », « s.d. », « n/a » et similaires comme cellules vides",
  "Cada tipo es una propuesta: revisa las selecciones y selecciones múltiples antes de importar. Elige una única columna de título; los valores incompatibles detendrán la importación para que puedas corregir el tipo.": "Chaque type est une proposition : vérifiez les sélections et sélections multiples avant d'importer. Choisissez une seule colonne de titre ; les valeurs incompatibles interrompront l'importation afin que vous puissiez corriger le type.",
  "Buscar opción": "Rechercher une option",
  "opciones más: escribe para filtrar": "options de plus : saisissez pour filtrer",
  "«-», «s.d.», «n/a», «?» y similares cuentan como juicio ausente.": "« - », « s.d. », « n/a », « ? » et similaires comptent comme un jugement absent.",
  "Tratar marcadores de vacío como ausentes": "Traiter les marqueurs de vide comme absents",
