  "Las imágenes muestran lo que se ve; la ficha, lo que el registro dice (título y propiedades). Ambas se combinan por posición, no por puntuación.": "Les images montrent ce qui est visible ; la fiche, ce que dit la fiche (titre et propriétés). Les deux sont combinées par rang, pas par score.",
