  "Volver al original": "Revenir à l'original",
  "Volver al original: quita el recorte y muestra la imagen completa.": "Revenir à l'original : supprime le recadrage et affiche l'image complète.",
  "Arrastra el marco o sus esquinas para elegir la parte que quieres ver.": "Faites glisser le cadre ou ses coins pour choisir la partie que vous voulez voir.",
