  "Primera indexación de las imágenes": "Première indexation des images",
  "Para la búsqueda semántica, Imago analiza cada imagen una vez. Elige con cuánto detalle: más calidad reconoce más cosas, pero tarda más.": "Pour la recherche sémantique, Imago analyse chaque image une fois. Choisissez le niveau de détail : une meilleure qualité reconnaît plus d'éléments, mais prend plus de temps.",
  "fichas": "fiches",
  "Calidad de la indexación": "Qualité de l'indexation",
  "Rápida": "Rapide",
  "Reconoce mejor los detalles pequeños: rótulos, rostros, objetos lejanos. Es la más lenta.": "Reconnaît mieux les petits détails : inscriptions, visages, objets éloignés. C'est la plus lente.",
  "Buen equilibrio entre detalle y velocidad: unas dos veces más rápida que la alta.": "Bon équilibre entre détail et vitesse : environ deux fois plus rapide que la qualité élevée.",
  "Unas cinco veces más rápida que la alta. Puede pasar por alto detalles pequeños.": "Environ cinq fois plus rapide que la qualité élevée. Peut manquer de petits détails.",
  "Puedes pausar la indexación cuando quieras. La calidad se cambia después en Configuración › Modelos, pero entonces hay que volver a indexar las imágenes.": "Vous pouvez mettre l'indexation en pause à tout moment. La qualité se modifie ensuite dans Réglages › Modèles, mais il faut alors réindexer les images.",
