  "La vista destacada es la que se abre al entrar en esta base de datos. Sin ninguna, se abre la tabla.": "La vue mise en avant est celle qui s'ouvre à l'entrée dans cette base de données. Sans vue mise en avant, le tableau s'ouvre.",
