  "De dónde toma sus registros esta vista: la tabla principal o una vista guardada": "D'où cette vue tire ses fiches : le tableau principal ou une vue enregistrée",
  "La galería, el mapa, la cronología, las estadísticas, las variantes, la red y el mapa visual se calculan sobre estos registros. Los filtros que añadas se aplican encima.": "La galerie, la carte, la chronologie, les statistiques, les variantes, le réseau et la carte visuelle sont calculés à partir de ces fiches. Les filtres que vous ajoutez s'appliquent par-dessus.",
