  "Cambiar el tipo no añade ni quita propiedades: indica para qué sirve la base (las Fuentes muestran primero sus registros enlazados).": "Changer le type n'ajoute ni ne retire de propriétés : il indique à quoi sert la base (les Sources affichent d'abord leurs fiches liées).",
  "Se llama como un título: da nombre a cada fila": "Se nomme comme un titre : donne un nom à chaque ligne",
