  "Cada valor de «{name}» se enlaza con el registro de la otra base que tenga el mismo valor. Mayúsculas, acentos de anchura y espacios de más no cuentan.": "Chaque valeur de « {name} » est liée à la fiche de l'autre base qui a la même valeur. Les majuscules, les accents, la largeur des caractères et les espaces superflus ne comptent pas.",
