  "Dejar de sincronizar las dos propiedades": "Arrêter de synchroniser les deux propriétés",
  "Esta relación solo se ve aquí. Puedes mostrarla también en «{db}», con los enlaces que ya tiene.": "Cette relation n'est visible qu'ici. Vous pouvez l'afficher aussi dans « {db} », avec les liens qu'elle a déjà.",
  "Fotografías, grabados o dibujos: título, imágenes, autor, fecha, ubicación, categorías y archivo.": "Photographies, gravures ou dessins : titre, images, auteur, date, emplacement, catégories et archive.",
  "Fuentes": "Sources",
  "Las vistas guardadas que filtraban por esta propiedad pasan a filtrar por los registros enlazados.": "Les vues enregistrées qui filtraient par cette propriété filtrent désormais par les fiches liées.",
  "Libros, revistas, álbumes y documentos: título, tipo, autor, editorial, lugar, año, identificador y cubierta.": "Livres, revues, albums et documents : titre, type, auteur, éditeur, lieu, année, identifiant et couverture.",
