  "Una propiedad calculada que muestra, en cada registro, el valor de los registros enlazados por «{name}». No copia datos: se actualiza sola y se puede filtrar, ordenar y contar.": "Une propriété calculée qui affiche, dans chaque fiche, la valeur des fiches liées par « {name} ». Elle ne copie pas de données : elle se met à jour toute seule et peut être filtrée, triée et comptée.",
