  "Ampliar y anotar": "Agrandir et annoter",
  "Zonas anotadas en esta imagen": "Zones annotées sur cette image",
  "Zonas etiquetadas en esta imagen": "Zones étiquetées sur cette image",
  "1 zona etiquetada en esta imagen": "1 zone étiquetée sur cette image",
  "{n} zonas etiquetadas en esta imagen": "{n} zones étiquetées sur cette image",
  "Zonas anotadas": "Zones annotées",
  "Calcular huellas visuales": "Calculer les empreintes visuelles",
  "Huellas": "Empreintes",
  "Red: muestra qué valores de dos o tres propiedades (por ejemplo, fotógrafo y lugar) aparecen juntos en los mismos registros.": "Réseau : montre quelles valeurs de deux ou trois propriétés (par exemple, photographe et lieu) apparaissent ensemble dans les mêmes fiches.",
  "Completar: propone valores para los registros vacíos de una propiedad a partir de las imágenes más parecidas que sí lo tienen. Nada se guarda hasta que lo aceptas.": "Compléter : propose des valeurs pour les fiches vides d'une propriété à partir des images les plus proches qui, elles, en ont une. Rien n'est enregistré avant que vous ne l'acceptiez.",
  "La primera vez puede tardar unos minutos: las partes de cada imagen se guardan y las búsquedas siguientes son inmediatas.": "La première fois, cela peut prendre quelques minutes : les parties de chaque image sont enregistrées et les recherches suivantes sont instantanées.",
  "Como base de datos nueva": "Comme nouvelle base de données",
  "Completar con imágenes parecidas": "Compléter avec des images similaires",
  "Para cada registro sin valor en la propiedad elegida, Imago busca las imágenes más parecidas que sí lo tienen y propone un valor. Las fechas se proponen como periodo atribuido, entre corchetes. Nada se guarda hasta que lo aceptas, y se puede deshacer.": "Pour chaque fiche sans valeur dans la propriété choisie, Imago cherche les images les plus proches qui en ont une et propose une valeur. Les dates sont proposées comme période attribuée, entre crochets. Rien n'est enregistré avant que vous ne l'acceptiez, et il est possible d'annuler.",
  "Confianza": "Confiance",
  "Alta": "Élevée",
  "Baja": "Faible",
  "Media o alta": "Moyenne ou élevée",
  "Solo alta": "Élevée seulement",
  "Descartar": "Ignorer",
  "{m} registros sin valor · {k} con valor · {v} con imagen indexada": "{m} fiches sans valeur · {k} avec valeur · {v} avec image indexée",
  "Buscando imágenes parecidas…": "Recherche d'images similaires…",
  "No hay propuestas para esta propiedad.": "Aucune proposition pour cette propriété.",
  "Imágenes parecidas": "Images similaires",
  "{n} aceptadas": "{n} acceptées",
  "Aceptar todas las de confianza alta": "Accepter toutes celles de confiance élevée",
  "Guardar las aceptadas": "Enregistrer les acceptées",
  "{n} valores guardados. Puedes deshacerlo con «Deshacer».": "{n} valeurs enregistrées. Vous pouvez annuler avec « Annuler ».",
  "Propone valores para los registros vacíos a partir de las imágenes más parecidas": "Propose des valeurs pour les fiches vides à partir des images les plus proches",
  "Completar": "Compléter",
  "Volver a las anotaciones": "Revenir aux annotations",
  "Dónde más aparece este detalle": "Où ce détail apparaît ailleurs",
  "Cargando el registro…": "Chargement de la fiche…",
  "Las claves de API y los modelos configurados se comparten entre todas las bases de datos de Imago.": "Les clés d'API et les modèles configurés sont partagés entre toutes les bases de données d'Imago.",
  "Modelos favoritos para los selectores independientes": "Modèles favoris pour les sélecteurs indépendants",
