  "Comprobar catálogo": "Vérifier le catalogue",
  "{provider} no incluye este modelo en su catálogo; su disponibilidad no está confirmada.": "{provider} n'inclut pas ce modèle dans son catalogue ; sa disponibilité n'est pas confirmée.",
  "Carga los modelos de un proveedor y márcalos con la estrella: aparecerán en los selectores de modelo.": "Chargez les modèles d'un fournisseur et marquez-les avec l'étoile : ils apparaîtront dans les sélecteurs de modèle.",
  "No se pudo comprobar: {providers}": "Vérification impossible : {providers}",
  "Favoritos que no aparecen en el catálogo": "Favoris absents du catalogue",
  "Estos favoritos no aparecen en el catálogo de su proveedor, pero podrían seguir funcionando como alias. Su disponibilidad no está confirmada. Quítalos con la × si ya no los usas.": "Ces favoris n'apparaissent pas dans le catalogue de leur fournisseur, mais pourraient continuer à fonctionner comme alias. Leur disponibilité n'est pas confirmée. Retirez-les avec la × si vous ne les utilisez plus.",
  "La comprobación está incompleta; la disponibilidad de los modelos no comprobados sigue sin confirmar.": "La vérification est incomplète ; la disponibilité des modèles non vérifiés reste non confirmée.",
  "Todos los favoritos aparecen en los catálogos comprobados.": "Tous les favoris figurent dans les catalogues vérifiés.",
