  "Filtrar por título…": "Filtrer par titre…",
  "Filtrar bases de datos por título": "Filtrer les bases de données par titre",
  "Borrar el filtro": "Effacer le filtre",
  "Cuadrícula": "Grille",
  "Las propiedades disponibles son las de las bases de datos elegidas.": "Les propriétés disponibles sont celles des bases de données choisies.",
  "Notificaciones": "Notifications",
  "Avisos de Imago": "Avis d'Imago",
  "No hay notificaciones.": "Aucune notification.",
  "Notificaciones actualizadas.": "Notifications actualisées.",
  "Sin novedades.": "Rien de nouveau.",
  "Los avisos están desactivados.": "Les avis sont désactivés.",
  "No se pudieron actualizar las notificaciones.": "Impossible d'actualiser les notifications.",
  "Activarlos en Ajustes": "Les activer dans les Réglages",
  "Abrir enlace": "Ouvrir le lien",
  "Marcar como leído": "Marquer comme lu",
  "Actualizando…": "Actualisation…",
  "Limpiar notificaciones": "Effacer les notifications",
  "Se quitarán los avisos que ves ahora. Los avisos que se publiquen más adelante seguirán apareciendo.": "Les avis que vous voyez actuellement seront retirés. Les avis publiés par la suite continueront d'apparaître.",
  "Recibir avisos de Imago": "Recevoir les avis d'Imago",
  "Las APIs remotas están desactivadas. Activa «Permitir APIs remotas» para introducir claves y consultar modelos.": "Les API distantes sont désactivées. Activez « Autoriser les API distantes » pour saisir des clés et consulter les modèles.",
  "Avisos publicados entre versiones (encuestas, incidencias conocidas, cambios importantes), en la campana de la cabecera. Se consulta un archivo público cada cuatro horas, sin enviar ningún identificador ni dato de tu colección. Al desactivarlo, Imago deja de hacer esa consulta.": "Avis publiés entre deux versions (enquêtes, incidents connus, changements importants), dans la cloche de l'en-tête. Un fichier public est consulté toutes les quatre heures, sans envoyer d'identifiant ni de données de votre collection. Si vous le désactivez, Imago cesse cette consultation.",
  "Vista de las bases de datos": "Vue des bases de données",
  "Ninguna base de datos coincide con «{q}».": "Aucune base de données ne correspond à « {q} ».",
  "Buscar también dentro de las imágenes (más lento la primera vez)": "Rechercher aussi à l'intérieur des images (plus lent la première fois)",
  "En todas las bases de datos": "Dans toutes les bases de données",
  "Comparar con los cinco primeros": "Comparer avec les cinq premières",
  "Las imágenes más parecidas se dividen en nueve partes y se marca la parte donde aparece el detalle.": "Les images les plus proches sont divisées en neuf parties et la partie où le détail apparaît est marquée.",
  "Compara el detalle con cada imagen entera. Funciona mejor cuando el detalle ocupa buena parte de la imagen.": "Compare le détail avec chaque image entière. Fonctionne mieux quand le détail occupe une bonne partie de l'image.",
  "Buscando dentro de las imágenes…": "Recherche à l'intérieur des images…",
  "Buscar este detalle": "Rechercher ce détail",
  "Cerrar la búsqueda": "Fermer la recherche",
  "Comprobando el índice visual…": "Vérification de l'index visuel…",
  "Para buscar por zonas, elige e instala en Ajustes un modelo de embeddings con visión.": "Pour rechercher par zones, choisissez et installez dans les Réglages un modèle d'embeddings avec vision.",
  "Para buscar por zonas, indexa antes las imágenes para la búsqueda semántica.": "Pour rechercher par zones, indexez d'abord les images pour la recherche sémantique.",
  "Arrastra sobre la imagen un recuadro para buscar elementos parecidos en las demás imágenes.": "Faites glisser sur l'image un cadre pour rechercher des éléments similaires dans les autres images.",
  "Arrastra sobre la imagen un recuadro alrededor de lo que quieres buscar.": "Faites glisser sur l'image un cadre autour de ce que vous voulez rechercher.",
  "Dibuja otro recuadro sobre la imagen para buscar otra cosa.": "Dessinez un autre cadre sur l'image pour rechercher autre chose.",
  "Buscar este detalle en las demás imágenes": "Rechercher ce détail dans les autres images",
  "Entonces y ahora": "Hier et aujourd'hui",
  "Fotografías actuales de Wikimedia Commons tomadas cerca de este lugar. Se envían a Wikimedia solo las coordenadas del lugar.": "Photographies actuelles de Wikimedia Commons prises près de ce lieu. Seules les coordonnées du lieu sont envoyées à Wikimedia.",
  "Distancia": "Distance",
  "Transparencia de la imagen actual": "Transparence de l'image actuelle",
  "Ver en Wikimedia Commons": "Voir sur Wikimedia Commons",
  "Buscando fotografías cercanas…": "Recherche de photographies proches…",
  "No hay fotografías de Wikimedia Commons a esa distancia. Prueba con una distancia mayor.": "Aucune photographie de Wikimedia Commons à cette distance. Essayez une distance plus grande.",
  "Fotografías tomadas desde el mismo punto y mirando en la misma dirección": "Photographies prises du même point et dans la même direction",
  "Vistas repetidas": "Vues répétées",
  "Grupos de fotografías tomadas a menos de 80 m entre sí y, si consta la dirección de la cámara, mirando hacia el mismo lado (±40°).": "Groupes de photographies prises à moins de 80 m les unes des autres et, si la direction de l'appareil est connue, orientées du même côté (±40°).",
  "No hay vistas repetidas. Indica la dirección de la cámara en la ubicación para afinar los grupos.": "Aucune vue répétée. Indiquez la direction de l'appareil dans l'emplacement pour affiner les groupes.",
  "con dirección": "avec direction",
  "Ver en el mapa": "Voir sur la carte",
  "Abrir en la mesa de comparación": "Ouvrir dans la table de comparaison",
  "Busca fotografías actuales tomadas cerca en Wikimedia Commons": "Recherche des photographies actuelles prises à proximité sur Wikimedia Commons",
  "Dirección de la cámara": "Direction de l'appareil",
