  "Cambiar el ancho del chat": "Redimensionner le chat",
  "Pregunta a tus bases de datos de imágenes. El chat responde con cifras, tablas y gráficos calculados sobre tus registros.": "Interrogez vos bases de données d'images. Le chat répond avec des chiffres, des tableaux et des graphiques calculés sur vos fiches.",
  "Para usar el chat, añade al menos un modelo de un proveedor en Ajustes › Proveedores de IA. También puedes conectar Ollama o LM Studio para usar un modelo en este ordenador.": "Pour utiliser le chat, ajoutez au moins un modèle d'un fournisseur dans Réglages › Fournisseurs d'IA. Vous pouvez aussi connecter Ollama ou LM Studio pour utiliser un modèle sur cet ordinateur.",
  "Abrir Ajustes": "Ouvrir les Réglages",
  "Regenerar respuesta": "Régénérer la réponse",
  "Copiar": "Copier",
