  "Eliminar chats": "Supprimer les chats",
  "Se eliminará «{name}» con todos sus mensajes. No se puede deshacer.": "« {name} » sera supprimé avec tous ses messages. Cette action est irréversible.",
  "Se eliminarán {n} chats con todos sus mensajes. No se puede deshacer.": "{n} chats seront supprimés avec tous leurs messages. Cette action est irréversible.",
  "Eliminar carpeta": "Supprimer le dossier",
  "Se eliminará «{name}» con sus subcarpetas. Sus chats no se borran: vuelven al historial general.": "« {name} » sera supprimé avec ses sous-dossiers. Ses chats ne sont pas supprimés : ils retournent dans l'historique général.",
