  "de las celdas esperan menos de 5 registros: la prueba es menos fiable. Reduce el número de valores o agrupa categorías.": "des cellules attendent moins de 5 fiches : le test est moins fiable. Réduisez le nombre de valeurs ou regroupez des catégories.",
