  "muy débil": "très faible",
  "débil": "faible",
  "moderada": "modérée",
  "fuerte": "forte",
  "Este recorrido señala las partes de la pantalla de Nodus Imago y explica para qué sirve cada una. Pulsa Siguiente o usa las flechas ← → del teclado. Puedes cerrarlo en cualquier momento con Saltar.": "Cette visite désigne les parties de l'écran de Nodus Imago et explique à quoi sert chacune. Cliquez sur Suivant ou utilisez les flèches ← → du clavier. Vous pouvez la fermer à tout moment avec Passer.",
  "La página de inicio muestra el siguiente paso recomendado y el estado de tu colección: número de bases de datos, de imágenes, de imágenes preparadas para la búsqueda semántica y de tareas en curso.": "La page d'accueil affiche la prochaine étape recommandée et l'état de votre collection : nombre de bases de données, d'images, d'images préparées pour la recherche sémantique et de tâches en cours.",
  "Aquí aparecen todas tus bases de datos con su número de registros. Pulsa sobre una para abrirla. El botón + crea una base de datos nueva.": "Toutes vos bases de données apparaissent ici avec leur nombre de fiches. Cliquez sur l'une pour l'ouvrir. Le bouton + crée une nouvelle base de données.",
  "Botones de la base de datos": "Boutons de la base de données",
  "Estos botones actúan sobre la base de datos abierta:": "Ces boutons agissent sur la base de données ouverte :",
  "Concordancia: compara las categorías asignadas por varios modelos de IA con las que has asignado tú.": "Concordance : compare les catégories attribuées par plusieurs modèles d'IA à celles que vous avez attribuées.",
  "Automatizaciones: hace que un modelo de IA rellene una propiedad en muchos registros a la vez. Los valores quedan como propuestas hasta que los apruebas.": "Automatisations : fait remplir une propriété par un modèle d'IA dans de nombreuses fiches à la fois. Les valeurs restent des propositions jusqu'à ce que vous les approuviez.",
  "Propiedades visibles: elige qué columnas se muestran en la tabla y en la galería.": "Propriétés visibles : choisissez les colonnes affichées dans le tableau et dans la galerie.",
  "Filtrar y ordenar: muestra solo los registros que cumplen unas condiciones y cambia su orden.": "Filtrer et trier : n'affiche que les fiches qui remplissent certaines conditions et change leur ordre.",
  "Importar: añade imágenes (archivos sueltos o una carpeta), registros desde un archivo CSV, un proyecto de Tropy o un manifiesto IIIF de una biblioteca digital.": "Importer : ajoute des images (fichiers isolés ou un dossier), des fiches depuis un fichier CSV, un projet Tropy ou un manifeste IIIF d'une bibliothèque numérique.",
  "Añadir registros: crea registros vacíos para rellenarlos a mano.": "Ajouter des fiches : crée des fiches vides à remplir à la main.",
  "Mostrar u ocultar el menú lateral": "Afficher ou masquer le menu latéral",
  "El logotipo de la esquina superior izquierda oculta el menú lateral para dejar más espacio a la tabla. Púlsalo otra vez para mostrarlo.": "Le logo en haut à gauche masque le menu latéral pour laisser plus de place au tableau. Cliquez dessus à nouveau pour l'afficher.",
  "Abre Ajustes › Interfaz, donde cambias el idioma, el modo claro u oscuro y los colores de la aplicación.": "Ouvre Réglages › Interface, où vous changez la langue, le mode clair ou sombre et les couleurs de l'application.",
  "Botones de la barra superior": "Boutons de la barre supérieure",
  "Estos botones están siempre disponibles:": "Ces boutons sont toujours disponibles :",
  "Lupa: abre la búsqueda global.": "Loupe : ouvre la recherche globale.",
  "Luna o sol: cambia entre el modo oscuro y el modo claro.": "Lune ou soleil : bascule entre le mode sombre et le mode clair.",
  "Reloj: muestra las tareas en segundo plano (importaciones, descargas de modelos, preparación de la búsqueda) y permite pausarlas o cancelarlas. El número indica cuántas hay en curso.": "Horloge : affiche les tâches en arrière-plan (importations, téléchargements de modèles, préparation de la recherche) et permet de les mettre en pause ou de les annuler. Le nombre indique combien sont en cours.",
  "Engranaje: abre los Ajustes.": "Engrenage : ouvre les Réglages.",
  "Secciones de Ajustes": "Sections des Réglages",
  "Los Ajustes están organizados en estas secciones:": "Les Réglages sont organisés en ces sections :",
  "Proveedores: activa las APIs externas y guarda sus claves.": "Fournisseurs : active les API externes et enregistre leurs clés.",
  "Modelos IA: elige qué modelo describe las imágenes, cuál clasifica y cuál se usa para la búsqueda semántica.": "Modèles IA : choisissez quel modèle décrit les images, lequel classe et lequel sert à la recherche sémantique.",
  "Modelos locales: descarga, verifica y elimina los modelos que se ejecutan en este ordenador.": "Modèles locaux : télécharge, vérifie et supprime les modèles qui s'exécutent sur cet ordinateur.",
  "Interfaz: idioma, modo claro u oscuro, colores, y botones para repetir la introducción y este recorrido.": "Interface : langue, mode clair ou sombre, couleurs, et boutons pour refaire l'introduction et cette visite.",
  "Rendimiento: cuántas tareas se ejecutan a la vez y cuántos recursos del ordenador pueden usar (perfil ligero, equilibrado o avanzado).": "Performances : combien de tâches s'exécutent en même temps et quelles ressources de l'ordinateur elles peuvent utiliser (profil léger, équilibré ou avancé).",
  "Actualizaciones y novedades: comprueba si hay versiones nuevas y elige si se descargan automáticamente.": "Mises à jour et nouveautés : vérifie s'il y a de nouvelles versions et permet de choisir si elles sont téléchargées automatiquement.",
  "Equivalencias de campos: agrupa columnas de bases de datos distintas que guardan el mismo dato, para filtrar por todas a la vez en la búsqueda global.": "Équivalences de champs : regroupe les colonnes de bases de données différentes qui stockent la même donnée, pour filtrer sur toutes à la fois dans la recherche globale.",
  "Almacenamiento y copias: carpeta de la colección, reconstrucción de índices y copias de seguridad.": "Stockage et sauvegardes : dossier de la collection, reconstruction des index et sauvegardes.",
  "Colas y tareas: lista de todas las tareas con su estado (en espera, en curso, completada o fallida). Desde aquí puedes pausarlas, reanudarlas o cancelarlas.": "Files d'attente et tâches : liste de toutes les tâches avec leur état (en attente, en cours, terminée ou échouée). Vous pouvez ici les mettre en pause, les reprendre ou les annuler.",
  "Descripciones y categorías con IA": "Descriptions et catégories avec l'IA",
  "Un modelo de IA puede proponer una descripción o una categoría para cada registro. Las propuestas no se guardan hasta que las revisas y las apruebas.": "Un modèle d'IA peut proposer une description ou une catégorie pour chaque fiche. Les propositions ne sont pas enregistrées tant que vous ne les avez pas vérifiées et approuvées.",
