  "Cada elemento puede tener un grupo y un tipo. Los iconos se ven en las celdas, en el mapa de patrimonio y en las estadísticas.": "Chaque élément peut avoir un groupe et un type. Les icônes s'affichent dans les cellules, sur la carte du patrimoine et dans les statistiques.",
