  "{n} elementos enlazados. Puedes revertir esta vinculación más abajo.": "{n} éléments liés. Vous pouvez annuler cette liaison plus bas.",
  "Busca en Wikidata cada elemento sin enlazar a partir de su nombre («Elemento - Ciudad»). Las propuestas no se guardan hasta que las aplicas; las de confianza alta llegan aceptadas y puedes cambiar cualquiera. Al aplicar se guardan el enlace, las coordenadas, la tipología sugerida y el elemento del que forma parte, solo donde la ficha no los tenga.": "Recherche dans Wikidata chaque élément non lié à partir de son nom (« Élément - Ville »). Les propositions ne sont enregistrées qu'une fois appliquées ; celles de confiance élevée arrivent acceptées et vous pouvez modifier n'importe laquelle. À l'application, on enregistre le lien, les coordonnées, la typologie suggérée et l'élément dont il fait partie, uniquement là où la fiche ne les a pas.",
  "Se enviarán a Wikidata los nombres de {n} elementos (solo el texto de cada uno), en grupos de diez.": "Les noms de {n} éléments (uniquement le texte de chacun) seront envoyés à Wikidata, par groupes de dix.",
