  "Informe y anexo técnico guardados.": "Rapport et annexe technique enregistrés.",
  "Informe guardado.": "Rapport enregistré.",
  "Un PDF con todo lo que hace falta para reproducir o evaluar tu análisis: los datos y su huella, las categorías, los modelos de IA con su revisión y sus instrucciones exactas, lo que revisaste y corregiste, la concordancia, los parámetros, las vistas y las estadísticas guardadas.": "Un PDF avec tout ce qui est nécessaire pour reproduire ou évaluer votre analyse : les données et leur empreinte, les catégories, les modèles d'IA avec leur révision et leurs instructions exactes, ce que vous avez vérifié et corrigé, la concordance, les paramètres, les vues et les statistiques enregistrées.",
  "Bases de datos del informe": "Bases de données du rapport",
  "relacionada": "liée",
  "Guardar también el anexo técnico (JSON) junto al PDF": "Enregistrer aussi l'annexe technique (JSON) avec le PDF",
