  "relleno con IA": "rempli par IA",
  "No se pudo calcular.": "Calcul impossible.",
  "década": "décennie",
  "año": "année",
  "En este equipo": "Sur cet ordinateur",
  "Registros que cumplen todas estas condiciones:": "Fiches remplissant toutes ces conditions :",
  "Registros que cumplen alguna de estas condiciones:": "Fiches remplissant l'une de ces conditions :",
  "Circulación de las imágenes": "Circulation des images",
  "Genealogía": "Généalogie",
  "Dónde y cuándo se publicó cada fotografía, cuánto tiempo después de la toma y con qué pies.": "Où et quand chaque photographie a été publiée, combien de temps après la prise de vue et avec quelles légendes.",
  "Cada fotografía reúne sus versiones (copias, escaneos, recortes y reproducciones) detectadas con sensibilidad equilibrada y confirmadas o corregidas por la investigación. La fecha de publicación es el año de la fuente que la imprime; la de la copia, la fecha del registro de cada versión; la de la toma, la de su obra fotográfica cuando se reunieron en una.": "Chaque photographie réunit ses versions (copies, scans, recadrages et reproductions) détectées avec une sensibilité équilibrée et confirmées ou corrigées par la recherche. La date de publication est l'année de la source qui l'imprime ; celle de la copie, la date de la fiche de chaque version ; celle de la prise de vue, celle de son œuvre photographique lorsqu'elles ont été réunies en une.",
  "{published} de las {families} fotografías con versiones tienen alguna publicación conocida, y {captions} se publicaron con pies distintos. La investigación indicó de qué versión procede {origins} de ellas.": "{published} des {families} photographies avec versions ont une publication connue, et {captions} ont été publiées avec des légendes différentes. La recherche a indiqué de quelle version provient {origins} d'entre elles.",
  "Entre la toma y la primera publicación pasaron {median} años de mediana (de {min} a {max}, en {n} fotografías con fecha de toma).": "Entre la prise de vue et la première publication, il s'est écoulé {median} ans en médiane (de {min} à {max}, sur {n} photographies avec date de prise de vue).",
  "Las fotografías más reproducidas: número de usos de cada una.": "Les photographies les plus reproduites : nombre d'usages de chacune.",
  "Primeras publicaciones conocidas por año.": "Premières publications connues par année.",
