  "Exportar CSV": "Exporter en CSV",
  "De la toma a cada publicación, en orden de fecha: cuándo la imprimió cada obra, cuándo se hizo cada copia, qué parte de la imagen conserva y con qué pie se publicó.": "De la prise de vue à chaque publication, par ordre de date : quand chaque œuvre l'a imprimée, quand chaque copie a été faite, quelle partie de l'image elle conserve et avec quelle légende elle a été publiée.",
