  "Cuántas regiones llevan cada etiqueta y en cuántas fotografías aparece.": "Combien de régions portent chaque étiquette et dans combien de photographies elle apparaît.",
  "Cada región delimita un elemento de la imagen y puede llevar varias etiquetas. Para cada etiqueta se cuentan las regiones validadas que la llevan y las fotografías en las que aparece. Las imágenes revisadas sin elementos se registran por separado de las que aún no se han revisado. Cada región guarda su origen, su confianza y su estado de validación.": "Chaque région délimite un élément de l'image et peut porter plusieurs étiquettes. Pour chaque étiquette, on compte les régions validées qui la portent et les photographies où elle apparaît. Les images vérifiées sans éléments sont comptées séparément de celles qui n'ont pas encore été vérifiées. Chaque région conserve son origine, sa confiance et son état de validation.",
  "Se revisaron {reviewed} de {images} imágenes ({share}); {empty} de ellas no tenían ningún elemento que etiquetar. Regiones: {sources}.": "{reviewed} images sur {images} ont été vérifiées ({share}) ; {empty} d'entre elles n'avaient aucun élément à étiqueter. Régions : {sources}.",
